// -----------------------------------------------------------------------------
// Journey Booking — Expire Request DTO
// -----------------------------------------------------------------------------

import { ApiPropertyOptional } from '@nestjs/swagger';
import { IsDateString, IsOptional } from 'class-validator';

/**
 * Optional request payload for expiring a Journey Booking.
 *
 * The booking public ID is supplied through the route parameter.
 * The correlation ID is generated by the controller.
 * The expiration timestamp is optional.
 */
export class ExpireJourneyBookingDto {
  @ApiPropertyOptional({
    description:
      'Explicit expiration timestamp. When omitted, the application uses the current time.',
    example: '2026-08-18T17:00:00.000Z',
    format: 'date-time',
  })
  @IsOptional()
  @IsDateString()
  expiredAt?: string;
}

export default ExpireJourneyBookingDto;
